static void Reset() { g_seq = g_baseCtorSeq = 0; g_addCalls = g_opCalls = g_scCalls = g_srcCalls = 0; g_addFunc = 0; g_addName[0] = g_srcName[0] = 0; }
int main()
{
    static CGameScriptInterface game;
    static CQ_BountyHuntScript parent;
    CCPPointerInfo info = { 1 };
    CBH_Hostage1 h;
    h.__vftable = 0; h.Game = &game; h.ParentClass = &parent; h.PMasterData = 0;
    h.Me.PImp.Data = (CScriptThingRuntime*)0x5678; h.Me.PImp.Info = &info;
    Reset();
    int live = g_strLive;
    h.Init();
    // reaction 34 switched off for this thing, first
    CHECK(g_opCalls == 1 && g_opThing == &h.Me && g_opReaction == 34 && !g_opEnabled && g_opSeq == 1);
    // the watcher is built (base ctor) and handed to the parent with an empty name
    CHECK(g_baseCtorSeq == 2 && g_addCalls == 1 && g_addSeq == 3 && g_addFunc != 0 && strcmp(g_addName, "") == 0);
    CSpawnedFuncPhase3* f = g_addFunc;
    CHECK(f && strcmp(Str(f->Name), "ParentClass.WatchForHostage1Killed") == 0 && f->ID == 0);
    CHECK(f && f->Func == &CQ_BountyHuntScript::WatchForHostage1Killed && f->PClass == &parent);
    CHECK(f && f->Par1.PImp.Data == (CScriptThingRuntime*)0x5678 && f->Par1.PImp.Info == &info);
    // the by-value argument copy is already gone by the time Add runs: Me + Par1
    CHECK(g_addRefs == 2);
    // then scared, then the villager-hostage opinion source, both on Me
    CHECK(g_scCalls == 1 && g_scThing == &h.Me && g_scScared && g_scSeq == 4);
    CHECK(g_srcCalls == 1 && g_srcThing == &h.Me && strcmp(g_srcName, "OPINION_SOURCE_VILLAGER_HOSTAGE") == 0 && g_srcSeq == 5);
    // every temporary string released; only the watcher's own name and region strings stay
    CHECK(g_strLive == live + 2);
    CHECK(info.References == 2 && h.Me.PImp.Info == &info);
    // a thing without a counted pointer: nothing to count, same calls
    CCPPointerInfo* none = 0;
    h.Me.PImp.Data = 0; h.Me.PImp.Info = none;
    Reset(); h.Init();
    CHECK(g_opCalls == 1 && g_addCalls == 1 && g_scCalls == 1 && g_srcCalls == 1);
    CHECK(g_addFunc && g_addFunc->Par1.PImp.Info == 0 && g_addFunc->Par1.PImp.Data == 0 && g_addRefs == -1);
    CHECK(info.References == 2);
    if (fails == 0) printf("00d167c0_TEST PASS\n");
    return fails;
}
